DROP TABLE IF EXISTS `koreksi_presensi`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `koreksi_presensi` (
  `id_koreksi` int NOT NULL AUTO_INCREMENT,
  `presensi_id` int NOT NULL,
  `jadwal_id` int NOT NULL,
  `status_sebelum` enum('hadir','terlambat','alpa','izin','libur','cuti') DEFAULT NULL,
  `keterangan_sebelum` text,
  `status_sesudah` enum('hadir','terlambat','alpa','izin','libur','cuti') NOT NULL,
  `keterangan_sesudah` text,
  `alasan_perubahan` text NOT NULL,
  `dokumen_bukti` varchar(255) DEFAULT NULL,
  `dikoreksi_oleh` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_koreksi`),
  KEY `presensi_id` (`presensi_id`),
  KEY `dikoreksi_oleh` (`dikoreksi_oleh`),
  KEY `idx_jadwal` (`jadwal_id`),
  KEY `idx_created` (`created_at`),
  CONSTRAINT `koreksi_presensi_ibfk_1` FOREIGN KEY (`presensi_id`) REFERENCES `presensi` (`id_presensi`) ON DELETE CASCADE,
  CONSTRAINT `koreksi_presensi_ibfk_2` FOREIGN KEY (`jadwal_id`) REFERENCES `jadwal` (`id_jadwal`) ON DELETE CASCADE,
  CONSTRAINT `koreksi_presensi_ibfk_3` FOREIGN KEY (`dikoreksi_oleh`) REFERENCES `users` (`id_user`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
